package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamSabaragamuwaFolkBank1 {
    private const val T = "සබරගමු නර්තන සම්ප්‍රදාය හා ජන නැටුම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("සබරගමු නර්තන සම්ප්‍රදායේ ප්‍රධානතම බෙරය කුමක්ද?", "දිගු දවුල", "ගැටබෙරය", "යක් බෙරය", "තබ්ලාව", "සබරගමු නර්තන අංග හා පහන් මඩු ශාන්තිකර්ම සඳහා වයන ප්‍රධාන බෙරය දිගු දවුලයි."),
        q("සබරගමු නර්තන සම්ප්‍රදාය ඓතිහාසිකව කේන්ද්‍රගත වී ඇති ප්‍රධාන පූජනීය ස්ථානය කුමක්ද?", "රත්නපුර මහ සමන් දේවාලය", "මහනුවර දළදා මාලිගාව", "කතරගම කිරිවෙහෙර", "නල්ලූර් කන්දසාමි කෝවිල", "සුමන සමන් දෙවියන් උදෙසා පවත්වන පූජා හා පෙරහැර ඇසුරෙන් සබරගමු නැටුම පෝෂණය විය."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ ආධුනික ශිල්පියෙකු පුහුණු වන මූලික පාද අභ්‍යාස මාලාව කුමක්ද?", "සබරගමු මණ්ඩි සරඹ හෙවත් මට්ටි සරඹ", "වන්නම් සරඹ 18", "තෙල්මේ පාලි සරඹ", "භරත අඩව් සරඹ", "දෙපා පළල් කර ලැසි ලෙස පද තබමින් මට්ටි හෙවත් මණ්ඩි සරඹ පුහුණු වේ."),
        q("සබරගමු නැටුමේදී ශිල්පියා පළඳින ප්‍රධාන සාම්ප්‍රදායික හිස් වැසුම හඳුන්වන්නේ කුමන නමකින්ද?", "ජටාව හෙවත් පායිම්පත් හිස් පළඳනාව", "වෙස් තට්ටුව", "රතු තෙල්මේ තොප්පිය", "සන්නි මුහුණ", "සුදු ජටාව හා පහිම්පත් සබරගමු ශිල්පියාගේ ගෞරවනීය හිස් සැරසිල්ලයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ මූලික ගමන් ශෛලිය හඳුන්වන විශේෂිත ලක්ෂණය කුමක්ද?", "ලැසි ගමන් හා වෘත්තාකාර නම්‍යශීලී චලන", "දැඩි හමුදා පෙළපාලි ගමන්", "එකම තැන කෙළින් සිටගෙන සිටීම", "බිම දිගේ උරගා යාම", "උඩරට සෘජු බවට වඩා මෘදු හා වක්‍රාකාර චලන සබරගමු නැටුමේ දක්නට ලැබේ."),
        q("සබරගමු දිගු දවුල වාදනය කිරීම සඳහා වාදකයා භාවිත කරන විශේෂිත උපකරණ යුගලය කුමක්ද?", "එක් අතකින් හා අනෙක් අතේ කඩිප්පුවකින්", "දෙඅතේම කඩිප්පු දෙකකින්", "පාද දෙකෙන් පමණි", "මුවින් පිඹීමෙන්", "දකුණු අතේ කඩිප්පුවකින් හා වම් අතේ අල්ලෙන් දවුල වාදනය කෙරේ."),
        q("සබරගමු නර්තනයේදී හිසේ බඳින 'පායිම්පත' හෙවත් 'පහිම්පත' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "හිස් මුදුනට හෝ නළලට පළඳින රිදී හෝ පබළු පටිය", "පාදයේ පළඳින ගෙජ්ජි පටිය", "බෙරයේ වරපටිය", "අතේ තබා ගන්නා කළය", "පුහුණුව අවසන් කළ ශිල්පියාට ගුරුවරයා විසින් හිසේ පායිම්පත් බැඳීම සිදු කරයි."),
        q("සබරගමු සම්ප්‍රදායේදී පූජනීය දෙවියන් ලෙස වැඩි ගෞරවයකින් පිදුම් ලබන දෙවියා කවුද?", "සුමන සමන් දෙවියන්", "ඉන්ද්‍ර දෙවියන්", "අග්නි දෙවියන්", "වරුණ දෙවියන්", "සමනල කඳු වැටිය හා රත්නපුර ප්‍රදේශයේ ආරක්ෂක දෙවියන් සමන් දෙවියන්ය."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ ආරම්භක වේදිකා සරඹ කොටස් අතර 'සවරම්' හා 'ගමන් පද' ඉගැන්වෙන්නේ කුමක් සඳහාද?", "විවිධ ශාන්තිකර්ම හා පෙරහැර නැටුම් සඳහා පදනම සැකසීමට", "සාම්ප්‍රදායික කෝලම් මුහුණු කැපීමට හුරු කිරීමට", "රාත්‍රී බලි රූප ඇඹීමේ පිළිවෙත පුහුණු කිරීමට", "පහතරට සන්නි යක්ෂ පෙළපාලි දෙබස් පුහුණු කිරීමට", "මූලික පද, මණ්ඩි සහ සරඹ හරහා සබරගමු ශෛලිය ප්‍රගුණ කෙරේ."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ භාවිත වන 'තේරුම් පද' යනු කුමක්ද?", "නැටුමක කවියේ හෝ තාලයේ අර්ථය දවුල් පදයෙන් හා චලනයෙන් පැහැදිලි කිරීම", "පද හා කවි අමතක කර නිහඬ අභිනයෙන් පමණක් නැටීම", "බෙර වාදනය නවතා අත්පුඩි ගසමින් පමණක් ඉදිරිපත් කිරීම", "සබරගමු ඇඳුම් වෙනස් කර වෙස්මුහුණු පැළඳගෙන නැටීම", "කවි අර්ථයට අනුරූපව දවුල් වාදනය හා අභිනය ගැළපීම තේරුම් පදවල විශේෂත්වයයි."),
        q("සබරගමු නැටුමේදී කලස් හෙවත් පුන්කලස් අතැතිව ඉදිරිපත් කරන විශේෂ නර්තන අංගය කුමක්ද?", "කලස් පද හෙවත් කලස් නැටුම", "වඩිග පටුන", "දහඅට සන්නිය", "හේවා කෝලම", "පත්තිනි හා සමන් දෙවි පූජාවලදී පුන් කළස් රැගෙන ශාන්තිදායක නර්තන ඉදිරිපත් කෙරේ."),
        q("සබරගමු නර්තන ඇඳුම් කට්ටලයේ උඩුකයට පළඳින ප්‍රධාන ආභරණය කුමක්ද?", "සබරගමු හැට්ටය, පබළු මාල හා උරමාලය", "උඩරට වෙස් තට්ටුව", "කෝලම් ලී මුහුණ", "සම් කබාය", "රතු සහ සුදු පැහැති රේන්ද හා පබළු ආභරණවලින් සබරගමු ඇඳුම අලංකාර වේ."),
        q("සබරගමු සම්ප්‍රදායේ 'හේවිසි වාදනය' සඳහා දිගු දවුලට අමතරව යොදාගන්නා අනෙක් වාද්‍ය භාණ්ඩ දෙක කුමක්ද?", "තම්මැට්ටම සහ හොරණෑව", "වයලීනය සහ පියානෝව", "සිතාරය සහ තබ්ලාව", "ගිටාරය සහ බංකු රබාන", "දේවාල හා විහාර පූජාවන්හි සාම්ප්‍රදායික හේවිසි කට්ටලය මෙය වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'පහන් මඩුව' පැවැත්වෙන ප්‍රධාන කාලසීමාව හා අරමුණ කුමක්ද?", "රාත්‍රී කාලයේ දොළොස් දෙවිවරුන් පිදීම හා ගමට සෙත් පැතීම", "උදෑසන වරුවේ සන්නි යකුන් උදෙසා පිදේනි පූජා තැබීම", "දහවල් කාලයේ කමත් ගොයම් කැපීමේ තරග පැවැත්වීම", "සන්ධ්‍යා කාලයේ පාසල් සරඹ සංදර්ශන පමණක් පැවැත්වීම", "සමන්, පත්තිනි හා කතරගම ආදී දෙවිවරුන් උදෙසා පහන් දල්වා ශාන්තිකර්මය පවත්වයි."),
        q("සබරගමු නැටුමේදී නැට්ටුවා පාදවල බඳින 'සිළම්බු' වලට අමතරව යොදාගන්නා කුඩා ශබ්ද උපකරණය කුමක්ද?", "ගෙජ්ජි වැල්", "හක්ගෙඩිය", "බටනලාව", "මද්දලය", "වළලුකර වටා බැඳි ගෙජ්ජි හා සිළම්බු පාද චලන සමඟ මිහිරි හඬක් නංවයි."),
        q("සබරගමු නර්තන කලාවේ එන 'සිංහවල්ලී' හෝ 'විජය කුවේණි' වැනි අස්න කවිවලින් පෙනෙන විශේෂත්වය කුමක්ද?", "සිංහල ජාතික ඉතිහාස පුවත් ගායනාත්මකව නර්තනයට එක් කර තිබීම", "විදේශීය ඔපෙරා ගීත සිංහලයට පරිවර්තනය කර ගැයීම", "බටහිර සොනට් හා ජෑස් තනු කවි ආකෘතියෙන් ගායනා කිරීම", "නූතන වේදිකා නාට්‍ය දෙබස් රිද්මයකින් තොරව කියවීම", "ලක්දිව මුල් ඓතිහාසික කථා සබරගමු යාතුකර්ම කවි සාහිත්‍යයේ රැඳී තිබේ."),
        q("සබරගමු සම්ප්‍රදායේ 'වන්නම්' ලෙස හඳුන්වන නැටුම් කොටස් උඩරට වන්නම්වලින් වෙනස් වන්නේ කෙසේද?", "දිගු දවුලේ තාලයට හා සබරගමු ලැසි ශෛලියට අනුව නිර්මාණය වී තිබීම", "වන්නම් කවි සම්පූර්ණයෙන් ඉංග්‍රීසි වීම", "කිසිදු බෙරයක් නොවැයීම", "වෙස්මුහුණු පැළඳ නැටීම", "සබරගමු සම්ප්‍රදායේ සිංහරාජ, බඹර, සැවුල් වැනි ආවේණික වන්නම් පවතී."),
        q("සබරගමු නැටුම් ක්ෂේත්‍රයේදී 'කිරිකෝඩු' නැටීම යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "නවක ශිල්පියෙකු ප්‍රථම වරට පහන් මඩුවක හෝ වේදිකාවක නැටුම් ඉදිරිපත් කිරීම", "පැරණි දිගු දවුල් හා තම්මැට්ටම් ඉවත දමා අලුත් බෙර ගැනීම", "මඩු ශාන්තිකර්මයක් අවසානයේ දෙවියන්ට කිරිබත් පිස පූජා කිරීම", "සබරගමු ගැමි නැටුම් අතරට අත් රබන් කරකැවීම හඳුන්වා දීම", "ගුරුවරයාගේ ආශිර්වාදය මැද ආධුනිකයා පළමු වරට රංගනයට පිවිසෙන අවස්ථාවයි."),
        q("සබරගමු 'දිගු දවුල' හි කඳ සාදා ඇති ස්වාභාවික දැව වර්ගය කුමක්ද?", "කොස්, කොහොඹ හෝ ඇහැල", "ප්ලාස්ටික්", "යකඩ", "බම්බු උණ", "විශාල හා ගැඹුරු ශබ්දයක් ලැබෙන පරිදි කොස් හෝ ඇහැල දැවයෙන් දවුල හාරා නිමවයි."),
        q("සබරගමු නර්තන ඇඳුමේ 'පහළ කොටස' සැකසීමේදී ශිල්පියා පළඳින දිගු සුදු රෙද්ද මත යොදන පටිය කුමක්ද?", "රතු ඉණ පටිය හා පොටවල්", "කළු සම් බෙල්ට් එක", "රිදී දම්වැල් දහයක්", "පිදුරු ලණු", "රතු ඉණ පටිය ඉණට තදින් බැඳ පහළ සුදු රැළි රෙද්ද ස්ථිර කරයි."),
        q("සබරගමු නැටුමේදී 'නැට්ටුවා සහ දවුල් වාදකයා' අතර ඇති සම්බන්ධතාව වඩාත් පැහැදිලි වන අංගය කුමක්ද?", "දවුල් පද සමඟ අත් හා පාදවල මෘදු වක්‍ර චලන බද්ධ වීම", "වාදකයා පිටුපස කාමරයක සිටීම", "නැට්ටුවා හිඳගෙන සිටීම", "දවුල බිම පෙරළීම", "දවුලේ ගැඹුරු හඬ සබරගමු ශෛලියට ගාම්භීර ලාලිත්‍යයක් එක් කරයි."),
        q("සබරගමු සම්ප්‍රදායේ 'මල් පද' හා 'ගමන් පද' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "මල් පද දේව පූජා අවස්ථාවේත් ගමන් පද සංචලනයේදීත් භාවිත වීම", "දෙකම බෙර අලුත්වැඩියාවට ගැනීම", "මල් පද ඉංග්‍රීසි ගීත වීම", "ගමන් පදවල පාද නොසෙල්වීම", "කාර්යය හා අවස්ථාව අනුව නැටුමේ පද රටා වෙනස් කෙරේ."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම් අතර 'පොල්කෙළි' නැටුමේදී නැට්ටුවන් අතැතිව සිටින පොල් ගෙඩි සකස් කරන්නේ කෙසේද?", "හොඳින් වියළි හා පිරිසිදු කළ පොල් කටු හෝ කුඩා පොල් ගෙඩි", "ලෙලි සහිත අමු පොල් ගෙඩි දහයක්", "ප්ලාස්ටික් බෝල", "ගල් කැබලි", "තාලයට එකට ගැසීමේදී පැහැදිලි හඬක් එන සේ සකස් කළ පොල් කටු හෝ ගෙඩි ගනී."),
        q("සිංහල ගැමි නැටුමක් වන 'වී පෙළීමේ නැටුම' හෙවත් 'කුලු නැටුම' තුළින් පෙන්වන්නේ කුමන ශ්‍රම ක්‍රියාවලියද?", "වී වලින් බොල් හා දහයියා ඉවත් කර පිරිසිදු සහල් ලබා ගැනීම", "මැණික් පතල් හාරමින් පොළොව යටින් ඉල්ලම් ගොඩ ගැනීම", "කෙත්වල පැසුණු ගොයම් දෑකැතිවලින් කපා අස්වැන්න නෙළීම", "දිය තොටින් මැටි කළගෙඩිවලට පිරිසිදු ජලය රැගෙන ඒම", "කුල්ල ඉහළ පහළ ගැසීම, පෙළීම හා ගැරීම නර්තන පියවරවලට හරවා ඇත."),
        q("ගැමි කාන්තාවන් විසින් ඉදිරිපත් කරන 'රබන් නැටුම' සාමාන්‍යයෙන් පවත්වන කණ්ඩායම් ස්වරූපය කුමක්ද?", "කාන්තාවන් පිරිසක් රවුමට හෝ පෙළට සිට අත් රබන් වයමින් නැටීම", "තනි පුද්ගලයෙකු බිම වැතිරී සිටීම", "පිරිමින් කඩු ගැසීම", "රබන් බිම දමා පෑගීම", "රබන් කරකවමින් හා උඩ දමා අල්ලමින් සාමූහික ප්‍රීතිය ප්‍රකාශ කෙරේ."),
        q("කළගෙඩි නැටුමේදී ගායනා කරන කවි බොහෝ විට ආරම්භ වන්නේ කුමන තේමාවකින්ද?", "බුදුන් වැඳීම, දෙවියන් පිදීම හා දිය තොටට යාම වර්ණනා කිරීමෙන්", "නාඩගම් රජ සභා දෙබස් හා තර්ක ඉදිරිපත් කිරීමෙන්", "විදේශීය නාවික ගමන් හා යුද පුවත් වර්ණනා කිරීමෙන්", "නූතන වේදිකා නාට්‍ය ගීත හා කෙටි කතා අනුකරණය කිරීමෙන්", "සෑම ගැමි කලාවක්ම පළමුව තෙරුවන් ගුණ සිහි කර ඇරඹීම සිරිතකි."),
        q("ලී කෙළි නැටුමේදී ශිල්පීන් දෙදෙනෙකු මුහුණට මුහුණ ලා සිට තාලයට ලී කෝටු ගැසීමෙන් ප්‍රකට වන්නේ කුමක්ද?", "සාමූහික අවබෝධය, කඩිසර බව හා රිද්ම නිරවද්‍යතාව", "එකිනෙකා සමඟ අමනාප වීම", "ලී කෝටු කැඩීමේ උත්සාහය", "තාලය වැරදීම", "වේගය වැඩි වන විට පවා ලී කෝටු නොවැරදී ගැසීම උසස් පුහුණුවක ප්‍රතිඵලයකි."),
        q("ගොයම් නැටුමේදී ශිල්පිනියන් අතේ තබා ගන්නා හෝ නිරූපණය කරන සාම්ප්‍රදායික ගොවි ආයුධය කුමක්ද?", "දෑකැත්ත (හෝ එහි චලන අභිනය)", "කියත", "මිටිය", "යතුර", "පැසුණු ගොයම් කරල් කපන අයුරු දෑකැති අභිනයෙන් අලංකාර ලෙස පෙන්වයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'මඩු සාදය' හෙවත් 'පහන් මඩුව' අවසානයේ පවත්වන පූජා අංගය කුමක්ද?", "ගරා යකුම හෙවත් ගරා නැටුම", "දහඅට සන්නිය", "සොකරි කෝලම", "මනමේ නාටකය", "යාගයේදී සිදු වූ ඇස්වහ කටවහ දෝෂ දුරු කිරීමට අවසානයේ ගරා යකා නටවනු ලැබේ."),
        q("සබරගමු නැටුමේදී 'තම්මැට්ටම' වාදනය කිරීමට ගන්නා කෝටු දෙක හඳුන්වන්නේ කුමන නමකින්ද?", "කඩිප්පු යුගලය", "බටනලා යුගලය", "තාලම්පට", "හක්ගෙඩි", "අග කොටස වක් වූ වේවැල් හෝ ලී කඩිප්පු යුගලයෙන් තම්මැට්ටම වයනු ලැබේ."),
        q("සබරගමු නර්තන පුහුණුවේදී 'පහිම්පත්' ලැබූ ශිල්පියෙකු හඳුන්වන ගෞරවනීය තත්ත්වය කුමක්ද?", "සම්පූර්ණ සබරගමු නැට්ටුවෙකු හෙවත් ගුරු පරපුරේ උරුමක්කාරයෙකු වීම", "ආධුනික දවුල් වාදකයෙකු ලෙස පමණක් පුහුණුව ලබා ගැනීම", "පහතරට කෝලම් හා සන්නි යකුමක විකට චරිතයක් නිරූපණය කිරීම", "මඩු සැරසිලි හා ගොක් කොළ කැටයම් නිර්මාණ ශිල්පියෙකු වීම", "වෙස් මංගල්‍යයට සමාන ගෞරවයක් සබරගමු පායිම්පත් බැඳීමෙන් හිමි වේ."),
        q("සබරගමු සම්ප්‍රදායේ 'නැටුම් කවි' ගායනා කරන විට බොහෝ විට යෙදෙන තාල රටාව කුමක්ද?", "මැදුම් හා විලම්බ ලය සහිත සෞම්‍ය ගායනා තාල", "ඉතා රළු කෑගැසීම්", "බටහිර ජෑස් රිද්ම", "තාල රහිත කියවීම්", "සබරගමු කවි තාල හදවතට දැනෙන සෞම්‍ය හා භක්තිමත් නාදයකින් යුක්තය."),
        q("ජන නැටුම් අතරින් 'සවරම් නැටුම' බොහෝ විට ඉදිරිපත් කරනු ලබන්නේ කුමන අවස්ථාවන්හිදීද?", "පෙරහැර, උත්සව හා වේදිකා සංදර්ශනවලදී", "ශෝකී අවමංගල්‍ය ආදාහන චාරිත්‍ර අවස්ථාවලදී", "නිහඬ භාවනා ආරාම ආගමික වැඩසටහන්වලදී", "රාත්‍රී සන්නි යකුම් පිදේනි පූජා අවස්ථාවලදී", "වර්ණවත් සවරම් යුගලය කරකවමින් ඉදිරිපත් කරන විචිත්‍ර ජන නැටුමකි."),
        q("සබරගමු නැටුමේදී 'මණ්ඩිය' නැවීමේදී දෙපා අතර පරතරය පිහිටුවිය යුතු ආකාරය කුමක්ද?", "උඩරටට වඩා මඳක් සමීපව එහෙත් සමබර පළලකින්", "දෙපා සම්පූර්ණයෙන් ඈඳාගෙන", "මීටර් දෙකක් ඈත් කරගෙන", "පාද බිම දිගා කරගෙන", "සබරගමු මණ්ඩිය වඩාත් මෘදු හා නම්‍යශීලී ඉරියව්වකින් සිදු කෙරේ."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේදී 'පත්තිනි මෑණියන්' වෙනුවෙන් ඉදිරිපත් කරන විශේෂිත පූජා නැටුමක් කුමක්ද?", "පන්තේරු හෝ සළු පූජා නැටුම", "වැදි කෝලම", "සන්නි යකුම", "හනුමා වන්නම", "සත්පත්තිනි ඇදහිල්ල සබරගමු පහන් මඩුවේදී ඉතා ඉහළින් පවත්වනු ලැබේ."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම්වල 'සමූහ හැඩතල' ලෙස බහුලව යොදාගන්නා ජ්‍යාමිතික රටා මොනවාද?", "වෘත්තාකාර, සමාන්තර පේළි සහ අර්ධ වෘත්තාකාර රටා", "අවිධිමත් පොදි ගැසීම්", "එකම කොණක සැඟවී සිටීම", "වේදිකාවෙන් බැස යාම", "ගැමි නැටුම්වල අලංකාරය රැඳී ඇත්තේ පැහැදිලි වට හා පෙළ රටා මතය."),
        q("සබරගමු සම්ප්‍රදායේ 'වට්ටම්' නැටුමේදී ශිල්පියා පෙන්නුම් කරන ප්‍රධානතම අංගය කුමක්ද?", "දවුල් තාලයට අනුව කැරකිලි හා පාද පියවරවලින් ජවය පෙන්වීම", "බිම හිඳ කවි ලිවීම", "කඩු මුවහත් කිරීම", "හිස්වැසුම ගලවා තැබීම", "මූලික පූජා අවසානයේ නැට්ටුවාගේ කුසලතාව මැන බලන කොටස මෙයයි."),
        q("සබරගමු නැටුමේදී ශිල්පියාගේ 'දෑත් චලන' වල ඇති සුවිශේෂී හැඩය කුමක්ද?", "දේශීය ලියවැල් මෙන් වක්‍රාකාර හා සුමට චලන", "කෝණයන්ගෙන් යුත් කෙටි තද චලන", "අත් සොලවන්නේම නැති ස්වභාවය", "මිට මොළවා සිටීම", "සබරගමු නර්තන ශෛලිය ලියවැල් චලන හා ලැසි ගමනට ප්‍රසිද්ධය."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ පැරණි ගුරු පරම්පරා විසින් ආරක්ෂා කරන ලද 'මන්ත්‍ර හා කවි' වල අරමුණ කුමක්ද?", "රෝග නිවාරණය, අස්වනු සශ්‍රීකත්වය හා දේව ආශිර්වාදය", "රාජ සභා නඩු හබ විසඳීම හා නීති තර්ක ඉදිරිපත් කිරීම", "විදේශීය නාට්‍ය පිටපත් සිංහලට පරිවර්තනය කර තැබීම", "ගැමි ජන ක්‍රීඩා තරගවල ජය පරාජය තීරණය කර දැක්වීම", "සමාජ සුභසිද්ධිය හා මානසික ශාන්තිය පතා මෙම සාහිත්‍යය රැකගෙන ඇත."),
        q("ජන නැටුම් අතරින් 'බුම්මැඩි නැටුම' හෝ 'රබන් නැටුම' ඉදිරිපත් කිරීමේදී යොදාගන්නා සාම්ප්‍රදායික අවස්ථාව කුමක්ද?", "අස්වැන්න නෙළීමේ සතුට හා සිංහල අලුත් අවුරුදු සැමරුම්", "ශෝකී අවමංගල්‍ය ආදාහන චාරිත්‍ර පවත්වන අවස්ථා", "රාත්‍රී මහ සොහොන් සමයම හා යක්ෂ පිදේනි අවස්ථා", "නිහඬ භාවනා වැඩසටහන් හා පිරිත් සජ්ඣායනා අවස්ථා", "ගැමි ප්‍රීතිය හා සාමූහික බව බෙදා ගන්නා උත්සවවලදී මේවා නටනු ලැබේ."),
        q("සබරගමු 'දිගු දවුල' කොතරම් බරින් හා ප්‍රමාණයෙන් යුක්ත වුවද එය වාදනය කරන්නේ කෙසේද?", "වරපටියකින් කරේ එල්ලා ඉණ මට්ටමින් තබාගෙන", "මේසයක් මත තබා දෙදෙනෙක් විසින්", "හිස මත තබාගෙන", "බිම වළලාගෙන", "සිටගෙන ඇවිදිමින් හා නටමින් වැයීමට හැකි සේ දවුල ඉණේ රඳවයි."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේදී 'අල්ලපද' යනුවෙන් හඳුන්වන්නේ කුමන අංගයක්ද?", "නැට්ටුවා සහ දවුල්කරු අතර ඒකාබද්ධ වන මූලික අත්-පා හා බෙර පද රටා", "නැටුම අවසානයේ විදුලි පහන් නිවීම", "බෙරයේ වරපටිය ගැලවීම", "ප්‍රේක්ෂකයන් අසුන් ගැනීම", "සබරගමු සරඹවලින් පසු ප්‍රගුණ කරන තාල පද කොටස මෙයයි."),
        q("පහතරට, උඩරට හා සබරගමු නර්තන අතරින් 'සමන් දේව වර්ණනා' වැඩි වශයෙන්ම හමුවන සම්ප්‍රදාය කුමක්ද?", "සබරගමු නර්තන සම්ප්‍රදාය", "පහතරට කෝලම් සම්ප්‍රදාය", "උඩරට ලී කෙළි සම්ප්‍රදාය", "ඉන්දියානු කථක් සම්ප්‍රදාය", "සමන් දෙවියන් හා සබරගමු පළාත අතර ඇති ගැඹුරු බැඳීම නැටුම් කවිවලින් පෙනේ."),
        q("ජන නැටුමක් වන 'චාමර නැටුම' ඉදිරිපත් කිරීමේදී ශිල්පීන් දෙඅතින් ගන්නා චාමර සාදා ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "සුදු හෝ වර්ණවත් කෙඳි හා ලී මිටකින්", "යකඩ දම්වැල්වලින්", "වීදුරු කැබලිවලින්", "කඩදාසි පෙට්ටිවලින්", "දෙවියන්ට පවන් සැලීම හා ගෞරව දැක්වීම චාමර නැටුමෙන් සංකේතවත් වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'මඩු පෙළපාලි' අතර දැකිය හැකි 'පාලි' අංගයකට උදාහරණයක් කුමක්ද?", "පන්දම් පාලිය හා සළු පාලිය", "වෙස් තට්ටු පාලිය", "කෝලම් හේවා පාලිය", "නාඩගම් රජ පාලිය", "පහන් මඩුවේදී ශුද්ධ කිරීම හා ආශිර්වාද ගෙනෙන පාලි කිහිපයක් ඉදිරිපත් කෙරේ."),
        q("සබරගමු නර්තන සම්ප්‍රදාය ප්‍රධාන වශයෙන් ව්‍යාප්ත වූ භූගෝලීය ප්‍රදේශය කුමක්ද?", "රත්නපුර සහ කෑගල්ල දිස්ත්‍රික්ක ආශ්‍රිත සබරගමු පළාත", "යාපනය අර්ධද්වීපය සහ මන්නාරම", "මඩකලපුව සහ ත්‍රිකුණාමලය වෙරළ තීරය", "ගාල්ල සහ මාතර වෙරළබඩ තීරය", "සබරගමු පළාතේ සංස්කෘතික හා ආගමික ජීවිතය සමඟ මෙම නර්තන සම්ප්‍රදාය බැඳී පවතී."),
        q("සබරගමු නර්තනයේදී හිස පළඳින 'පායිම්පත' සමඟ උඩුකයට පළඳින දිගු උර ආභරණය කුමක්ද?", "රතු හෝ සුදු පැහැති උරමාලය සහ පබළු මාල", "පහතරට රකුසු මුහුණ", "ලෝහමය හෙල්මටය", "කඩු කොපුව", "පබළු මාල සහ උරමාලය සබරගමු ඇඳුම් කට්ටලයට අලංකාර පෙනුමක් ලබා දෙයි."),
        q("සබරගමු 'දිගු දවුල' කරේ එල්ලා ගන්නා පටිය හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "දවුල් වරපටිය හෙවත් කරපටිය", "සිළම්බු පටිය", "ජටා පටිය", "තාලම් නූල", "දවුල සමබරව ඉණ මට්ටමින් රඳවා ගැනීමට කරපටිය භාවිත කරයි."),
        q("සබරගමු නැටුමේදී ශිල්පියා පාදවලින් කරන 'සරඹ' පුහුණුව ආරම්භයේදී ශරීරය තබා ගන්නා ඉරියව්ව කුමක්ද?", "දෙපා පළල් කර මඳක් නැවී සිටින සබරගමු මණ්ඩිය", "එක පාදයකින් පමණක් සිටගැනීම", "බිම වැතිරී සිටීම", "දෙපා සම්පූර්ණයෙන් ළං කර සිටීම", "මණ්ඩි ඉරියව්වෙන් පාද අභ්‍යාස කිරීමෙන් ශරීර සමබරතාව ගොඩනැගේ."),
        q("සබරගමු සම්ප්‍රදායේ 'මල් පද' ඉදිරිපත් කිරීමේ ප්‍රධානතම අරමුණ කුමක්ද?", "දෙවියන් උදෙසා මල් පූජා කරමින් ආශිර්වාදය ලබා ගැනීම", "වේදිකාව සුද්ධ පවිත්‍ර කිරීම", "ප්‍රේක්ෂකයන් හිනැහවීම", "තරග ලකුණු ගණන් කිරීම", "පූජනීය භක්තිය මල් පද රංගනයෙන් ප්‍රකාශ කෙරේ."),
        q("සබරගමු 'පහන් මඩුවක' තොරණ ඉදිරියේ පූජා ආසන සකස් කරන්නේ කුමන ද්‍රව්‍ය යොදාගෙනද?", "පුවක් පටි, ගොක් කොළ සහ කෙසෙල් කඳන්", "යකඩ දඬු සහ සිමෙන්ති", "වීදුරු පුවරු සහ ප්ලාස්ටික්", "ගල් ලෑලි සහ තාර", "දේශීය ශාක කොටස් යොදා සාම්ප්‍රදායික යහන් හා තොරණ නිමවයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'තේරුම් පද' වලට සමගාමීව ගායනා කරන පද්‍ය කොටස් මොනවාද?", "කවි සහ සීපද", "බටහිර සොනට් ගීත", "ලාංකේය බයිලා", "නාඩගම් දෙබස් පමණි", "කවි අර්ථය දවුල් තාලයට ගැළපීම සබරගමු සම්ප්‍රදායේ සුවිශේෂ ලක්ෂණයකි."),
        q("ජන නැටුම් අතරින් 'සවරම් නැටුම' සඳහා යොදාගන්නා 'සවරම' කුමන හැඩයකින් යුක්ත වේද?", "වර්ණවත් කෙඳි ගැටගැසූ කුඩා පඳුරක් බඳු දණ්ඩකි", "වටකුරු පිත්තල තැටියකි", "මැටි කළයකි", "දිගැති උණ බටයකි", "සවරම් යුගලය දෑතින් කරකවමින් රිද්ම රටා මැවීම ජනප්‍රිය අංගයකි."),
        q("සිංහල ජන නැටුමක් වන 'පොල්කෙළි නැටුමේදී' නැට්ටුවන් අත්වල තබා ගන්නේ මොනවාද?", "පිරිසිදු කළ පොල් කටු යුගලයකි", "වියළි ලී කෝටු යුගලයකි", "කුඩා රබන් යුගලයකි", "මැටි කළ යුගලයකි", "පොල් කටු එකට ගැසීමෙන් පැහැදිලි තාල ශබ්දයක් ජනිත වේ."),
        q("ගොයම් නැටුමේදී නැට්ටුවන් අනුකරණය කරන ප්‍රධාන කෘෂිකාර්මික කාර්යයන් මොනවාද?", "වී වැපිරීම, පැළ සිටුවීම සහ ගොයම් කැපීම", "පොල් කැඩීම සහ රා මැදීම", "වැව් හෑරීම සහ බැමි බැඳීම", "වළං සෑදීම සහ පිළිස්සීම", "වී ගොවිතැනේ එදිනෙදා ක්‍රියාකාරකම් සෞම්‍ය නර්තන චලන බවට පත් කර ඇත."),
        q("කළගෙඩි නැටුමේදී කාන්තාවන් දිය තොටට යන ගමන හා දිය පුරවා ගැනීම දැක්වීමට භාවිත කරන්නේ කුමක්ද?", "සැහැල්ලු මැටි කළගෙඩි", "පිත්තල තැටි", "ලී කෝටු", "වේවැල් කුලු", "මැටි කළගෙඩි හිස, උකුල හා අත මත රඳවමින් විචිත්‍ර චලන දක්වයි."),
        q("ලී කෙළි නැටුම සාම්ප්‍රදායිකව ප්‍රචලිත වී ඇත්තේ කුමන උත්සව අවස්ථාවලදීද?", "සිංහල අලුත් අවුරුදු උත්සව සහ ගැමි පෙරහැර", "අවමංගල්‍ය පෙරහැර", "ශාන්තිකර්ම අවසාන රාත්‍රිය පමණි", "රාජ සභා නඩු විභාග", "විනෝදය හා එකමුතුකම පිළිබිඹු කරන සාමූහික ජන ක්‍රීඩා නැටුමකි."),
        q("සබරගමු නැටුමේ 'පායිම්පත් බැඳීම' යන මංගල චාරිත්‍රය සමඟ සැසඳෙන උඩරට චාරිත්‍රය කුමක්ද?", "වෙස් බැඳීමේ මංගල්‍යය", "දහඅට සන්නි මංගල්‍යය", "හේවා කෝලම", "බලි ඇඹීම", "ශිෂ්‍යයාගේ ප්‍රවීණත්වය පිළිගැනීමේ ගෞරවනීය පියවරක් ලෙස මෙය සිදු කෙරේ."),
        q("සබරගමු නර්තන ඇඳුමේ හිසට අඳින 'සුදු ජටාව' බැඳීමෙන් නිරූපණය වන සංකේතය කුමක්ද?", "ශිල්පියාගේ පවිත්‍රතාව, විනය සහ ගුරු ගෞරවය", "කෝලම් නාටකයේ විකට චරිත ස්වභාවය", "වැදි නැටුමේ දඩයම් යුද සූදානම", "රට යකුමේ රිද්දි බිසවුන්ගේ හැඩහුරුකම", "පිරිසිදු සුදු රෙද්දෙන් හිස බැඳ පායිම්පත පැළඳීම සම්ප්‍රදායික ගෞරවයයි."),
        q("සබරගමු 'කලස් නැටුමේදී' නැට්ටුවන් අතේ ගෙන යන පුන්කලසින් සංකේතවත් වන්නේ කුමක්ද?", "සෞභාග්‍යය, සශ්‍රීකත්වය සහ ශුභ නිමිත්ත", "දුර්භික්ෂය සහ පරාජය", "යුද බිය", "වැඩ නිමාවීම", "පිරුණු කළය හෙවත් පුන්කලස පෙරදිග සංස්කෘතියේ මංගල වස්තුවකි."),
        q("සබරගමු සම්ප්‍රදායේ 'දිගු දවුල' කඩිප්පුවෙන් වාදනය කරන පැත්ත හඳුන්වනු ලබන්නේ කෙසේද?", "දකුණු ඇස හෙවත් කඩිප්පු අත", "වම් ඇස", "මැද කඳ", "වරපටි පැත්ත", "දකුණු අතේ කඩිප්පුවෙන් තියුණු හා රිද්මයානුකූල හඬ උපදවයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේදී භාවිත කරන 'ගමන් පද' කොටස් කිහිපයක් නම් කරන්න.", "සමන් දේව ගමන් පදය සහ හස්ති ගමන් පදය", "සන්නි ගමන් පදය සහ කෝලම් පදය", "භරත අඩව්ව සහ තෙල්මේ පදය", "වඩිග පටුන සහ සූනියම් පදය", "විවිධ සතුන් හා දේව ගමන් විලාස අනුව සබරගමු ගමන් පද සකසා ඇත."),
        q("ජන නැටුම් අතරින් 'කුළු නැටුම' ඉදිරිපත් කිරීමේදී නැට්ටුවන් භාවිත කරන ප්‍රධාන උපකරණය කුමක්ද?", "වේවැල්වලින් වියූ සාම්ප්‍රදායික කුල්ල", "තඹ හා පිත්තල මිශ්‍ර කළ ලෝහ තැටිය", "හොඳින් ඔප දැමූ සිනිඳු පොල් කටු යුගලය", "සැහැල්ලු පිළිස්සූ ගැමි මැටි කළගෙඩිය", "වී පෙළීමේ ක්‍රියාවලිය කුල්ල ආධාරයෙන් නර්තන රටා ලෙස පෙන්වයි."),
        q("ගැමි ජන නැටුමක් වන 'රබන් නැටුම' සඳහා වයන අත් රබාන සාදා ඇති ප්‍රධාන අමුද්‍රව්‍ය මොනවාද?", "ලී රාමුවක් සහ එළු හෝ තලගොයි සම", "පිත්තල තැටියක් සහ යකඩ කම්බි", "මැටි බඳුනක් සහ රෙදි", "උණ බට සහ නූල්", "සැහැල්ලු ලී වළල්ලක තුනී සම තදින් ගසා අත් රබාන නිමවයි."),
        q("සබරගමු නැටුමේ 'වට්ටම්' නැටීමේදී දවුලේ වේගය ක්‍රමයෙන් වැඩි වීමත් සමඟ නැට්ටුවා කරන්නේ කුමක්ද?", "වේගවත් කැරකිලි සහ පාද පියවරවලින් තාලයට අනුගත වීම", "නැටුම මැද නතර වීම", "බිම වාඩි වී අත්පුඩි ගැසීම", "වේදිකාවෙන් පිටව යාම", "ලය වැඩි වන විට නැට්ටුවාගේ ජවය හා ශිල්පීය හැකියාව ඉස්මතු වේ."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ 'මුද්‍රා' භාවිතය බහුලව දැකිය හැක්කේ කුමන නැටුම් කොටස්වලදීද?", "සබරගමු වන්නම් සහ තේරුම් පද අභිනයේදී", "දිගු දවුල හා තම්මැට්ටම සෑදීමේදී පමණි", "මඩු තොරණ හා ගොක් කොළ බැඳීමේදී පමණි", "සබරගමු වස්ත්‍රාභරණ ඇඳීමේ චාරිත්‍රයේදී", "කවි අර්ථ නිරූපණය සඳහා සුමට හස්ත මුද්‍රා භාවිත කෙරේ."),
        q("ජන නැටුම් පුහුණු වන සිසුන් 'සමූහ නැටුම්' ඉදිරිපත් කිරීමේදී අවධානය යොමු කළ යුතු ප්‍රධානතම සාධකය කුමක්ද?", "සියලු දෙනාම එකම තාලයට හා එකම උස මට්ටමට අනුව චලන කිරීම", "සමූහයෙන් වෙන් වී තනිවම ඉදිරියට පැන රඟ දැක්වීම", "එක් එක් නැට්ටුවා තමන් කැමති වෙනස් තාලයකට නැටීම", "අත් චලන නවතා බිම බලාගෙන එකම තැන සිටගෙන සිටීම", "සමූහ ඒකාග්‍රතාව ජන නැටුමක අලංකාරය තීරණය කරයි."),
        q("සබරගමු සම්ප්‍රදායේ 'සළු පාලිය' රඟ දැක්වීමේදී නැට්ටුවා අතැතිව සිටින ප්‍රධාන වස්තුව කුමක්ද?", "පිරිසිදු සුදු හෝ වර්ණවත් දිගු සළුවක්", "ලෝහ තලයකින් යුත් කෙටි අත් කඩුවක්", "කැටයම් කළ සුමට පැතලි ගල් ලෑල්ලක්", "කළුවර දැවයෙන් සෑදූ ලී කෝටු යුගලක්", "පත්තිනි දේව පූජාව හා ආශිර්වාදය සංකේතවත් කරමින් සළුව වනමින් නටයි."),
        q("සබරගමු 'පහන් මඩුව' ශාන්තිකර්මයේදී ආරාධනා කරනු ලබන ප්‍රධාන දෙවිවරුන් දෙදෙනා කවුද?", "සුමන සමන් දෙවියන් සහ පත්තිනි දේවිය", "සිකුරු සහ අඟහරු ග්‍රහයන්", "ග්‍රීක සියුස් සහ හේරා", "රෝම නෙප්චූන් සහ මාර්ස්", "සමන් හා පත්තිනි ඇදහිල්ල සබරගමු පළාතේ ඉතා බැතිමත්ව පවතී."),
        q("ජන නැටුමක් වන 'තාලම් නැටුමේදී' ප්‍රධාන වාද්‍ය හා නර්තන උපකරණය කුමක්ද?", "තාලම්පට යුගලය", "මැටි කළගෙඩිය", "දිගු දවුල", "හොරණෑව", "තාලම්පට දෙඅතින් ගසමින් රිද්ම රටා මැවීම මෙම නැටුමේ ලක්ෂණයයි."),
        q("සබරගමු නැටුම් සම්ප්‍රදායේ 'වන්නම්' අතර හමුවන ප්‍රසිද්ධ වන්නම් දෙකක් නම් කරන්න.", "සැවුලා වන්නම සහ මයුරා වන්නම", "දහඅට සන්නි වන්නම සහ කෝලම් වන්නම", "කථක් වන්නම සහ ඔඩිසි වන්නම", "බයිලා වන්නම සහ රබන් වන්නම", "උඩරටට අමතරව සබරගමු පද හා කවි අනුව ගොඩනැඟුණු වන්නම් රැසක් ඇත."),
        q("සිංහල ගැමි නැටුමක් වන 'චාමර නැටුම' ඉදිරිපත් කිරීමේදී ප්‍රකාශ වන ප්‍රධාන හැඟීම කුමක්ද?", "පූජනීය ගෞරවය, සෞම්‍ය බව හා අලංකාරය", "රෞද්‍ර කෝපය", "භයානක තැතිගැන්ම", "හාස්‍ය උපහාසය", "චාමර සැලීම අතීතයේ සිට රජවරුන්ට හා දෙවියන්ට දැක්වූ ගෞරවයකි."),
        q("සබරගමු නර්තනයේ 'අත් චලන' හා 'උඩරට අත් චලන' අතර පෙනෙන පැහැදිලි වෙනස කුමක්ද?", "සබරගමු අත් චලන වඩාත් මෘදු හා වක්‍රාකාර වන අතර උඩරට චලන සෘජු හා කෝණික වේ", "සබරගමු නැටුමේදී අත් චලන කිසිසේත් සිදු නොකර පාද පමණක් තැබීම", "උඩරට නැටුමේදී අත් දෙකම සම්පූර්ණයෙන් පිටුපසට බැඳ නැටීම", "සම්ප්‍රදායන් දෙකේම අත් චලන එක හා සමාන බටහිර බැලේ ශෛලියක් ගැනීම", "ශෛලීය අනන්‍යතාව මෙම අත් චලන රටාවන්ගෙන් පහසුවෙන් හඳුනාගත හැකිය."),
        q("සබරගමු නැටුමේ 'පාද චලන' පුහුණුවේදී ශිෂ්‍යයාට ඉගැන්වෙන 'සුළු ගමන' හා 'මැදුම් ගමන' අයත් වන්නේ කුමන කොටසටද?", "මූලික ගමන් පද කොටසට", "සන්නි මුහුණු කොටසට", "බලි ඇඹීමේ කොටසට", "හොරණෑ පිඹීමේ කොටසට", "විවිධ ලය වේගයන්ට අනුව ගමන් පියවර හුරු කිරීම මින් සිදු වේ."),
        q("ජන නැටුම් සඳහා ගායනා කරන 'ජන කවි' වලින් හෙළි වන ප්‍රධාන සමාජ ලක්ෂණය කුමක්ද?", "ගැමි ජනතාවගේ එදිනෙදා ජීවිතය, ශ්‍රමය, විශ්වාස හා සතුට", "රාජ සභාවේ පැවති සංස්කෘත නාට්‍ය දෙබස් හා රීති", "පහතරට සන්නි යකුන් සඳහා කියැවෙන රහස් මන්ත්‍ර විධි", "විදේශීය සංගීත සම්ප්‍රදායන්හි එන ස්වර ප්‍රස්තාර නීති", "ජන කවි යනු අපේ ගැමි සංස්කෘතියේ ජීවමාන ලේඛනයයි."),
        q("සබරගමු නර්තන ඇඳුම් කට්ටලයේ පහළ කොටස සඳහා පළඳින දිගු සුදු රෙද්ද හඳුන්වන්නේ කුමන නමකින්ද?", "රැළි හඟල හෙවත් පහළ උල්පත් රෙද්ද", "සන්නි සළුව", "කෝලම් කලිසම", "වෙස් කබාය", "ඉණ වටා රැළි තබා අඳින සුදු රෙද්ද සබරගමු නැටුමේ චලනවලට පහසුව සලසයි."),
        q("සබරගමු 'පහන් මඩුවක' දී නවක ශිල්පීන් ආශිර්වාද ලබා රංගනයට පිවිසීමේදී ගායනා කරන ආරම්භක අංගය කුමක්ද?", "නමස්කාර කවි හා සභා අවසර කවි", "ලී කෙළි කවි", "ගොයම් කවි", "කළගෙඩි කවි", "තෙරුවන්ට, දෙවියන්ට හා ගුරුවරුන්ට වැඳ අවසර ගැනීම සිරිතකි."),
        q("ගොයම් නැටුම ඉදිරිපත් කරන කාන්තාවන්ගේ ඇඳුම ලෙස සාම්ප්‍රදායිකව භාවිත වන්නේ කුමක්ද?", "චාම් මල් රෙද්ද සහ හැට්ටය (ගැමි කාන්තා ඇඳුම)", "පිරිමි වෙස් ඇඳුම", "දහඅට සන්නි මුහුණ", "බටහිර සපත්තු සහ කබාය", "ගැමි කුඹුරේ වැඩ කරන කාන්තාවගේ ස්වභාවය ඇඳුමින්ද නිරූපණය වේ."),
        q("පොල්කෙළි නැටුම හා ලී කෙළි නැටුම අතර ඇති ප්‍රධාන පොදු ලක්ෂණය කුමක්ද?", "දෙකම ද්‍රව්‍ය එකට ගැසීමෙන් තාල නාද උපදවන සමූහ ජන නැටුම් වීම", "දෙකම මුහුණු ආවරණ පැළඳීම", "දෙකම තනි පුද්ගල ශෝක නැටුම් වීම", "දෙකම බිම වාඩි වී නැටීම", "ජන ක්‍රීඩා හා සාමූහික විනෝදාස්වාදය මේ නැටුම් දෙකෙන්ම ප්‍රකට වේ."),
        q("සබරගමු නැටුමේදී ශිල්පියා පාදවල පළඳින 'සිළම්බු' නිමවා ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "පිත්තල හෝ ලෝකඩ ලෝහයෙන්", "මැටියෙන්", "ප්ලාස්ටික්වලින්", "කඩදාසියෙන්", "ඇතුළත කුඩා ලෝහ ඇට දැමූ කුහර ලෝහ වළලු සිළම්බු ලෙස පාදවල පළඳියි."),
        q("ගැමි ජන නැටුමක් වන 'තෙල්මේ' නොවන 'කමත් නැටුම' පිළිබිඹු කරන්නේ කුමක්ද?", "අස්වැන්න පාගා වී වෙන් කර ගැනීමේ කමත් ක්‍රියාවලිය", "මුහුදේ මසුන් ඇල්ලීම", "පතල් කැණීම", "ගෙවල් සෑදීම", "කමතේ ගැමි ශ්‍රමය හා පූජනීය චාරිත්‍ර මෙම ජන නැටුමෙන් දැක්වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'වැඩිහිටි ගුරුවරුන්' ශිෂ්‍යයාට ඉගැන්වීමට පෙර සිදු කරන ආචාර චාරිත්‍රය කුමක්ද?", "බුලත් අතක් දී ගුරු පඬුරු පිළිගැන්වීම", "ආරම්භයේදීම සියලු හස්ත මුද්‍රා තහනම් කිරීම", "පැරණි කෝලම් වෙස්මුහුණු ඉවත් කර දැමීම", "තාලම්පට පසෙක තබා අත්පුඩි පමණක් ගැසීම", "පෙරදිග කලා අධ්‍යාපනයේදී බුලත් හුරුල්ලෙන් ගුරු ගෞරවය ප්‍රකාශ කිරීම සිරිතකි."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ 'ගමන් පද' ඉගැන්වීමේදී ගුරුවරයා භාවිත කරන කාල ලය මොනවාද?", "විලම්බ, මධ්‍ය සහ ද්‍රුත යන ලය තුනම", "විලම්බ ලය පමණක්", "කිසිදු ලයක් නොමැත", "නිශ්චල ඉරියව් පමණක්", "සෙමින් ආරම්භ කර මැදුම් හා වේගවත් ලයට ගමන් පද ඉදිරිපත් කෙරේ."),
        q("ජන නැටුමක් වන 'පන්දම් නැටුම' ඉදිරිපත් කිරීම සඳහා වඩාත්ම උචිත පරිසරය කුමක්ද?", "එළිමහන් රාත්‍රී වේදිකාව හෝ පෙරහැර මාර්ගය", "පටු පන්ති කාමරය ඇතුළත", "කඩදාසි ගබඩාවක් තුළ", "දහවල් තද හිරු එළියේ", "පන්දම් ආලෝකයේ චමත්කාරය රාත්‍රී විවෘත පරිසරයේදී මැනවින් දිස්වේ."),
        q("සබරගමු නැටුමේ 'පද කොටසක්' අවසන් කිරීමේදී නැට්ටුවා හා දවුල් වාදකයා අතර තිබිය යුතු එකඟතාව කුමක්ද?", "දෙදෙනාම එකම තාල මාත්‍රාවේදී නිවැරදිව තීර්මානය අවසන් කිරීම", "දෙදෙනා වෙන වෙනම වේලාවන්හිදී තම කොටස අවසන් කිරීම", "නැටුම අවසන් වීමට පෙර දවුල් වාදකයා වේදිකාවෙන් පිටව යාම", "තීර්මානය නැටීම මඟ හැර නැට්ටුවා ආරම්භක මණ්ඩියේ සිටීම", "තාල ඒකාග්‍රතාව රංගනයේ ප්‍රවීණත්වය පෙන්නුම් කරයි."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම් වර්තමාන පාසල් සෞන්දර්ය උත්සවවලදී වැදගත් වන්නේ ඇයි?", "සිසුන් තුළ දේශීය සංස්කෘතික අගයන් හා සාමූහිකත්වය පෝෂණය කරන බැවින්", "පාසල් විෂය මාලාවේ අනෙකුත් විෂයන් අමතක කරවීමට හේතු වන බැවින්", "පුහුණුවීම් මඟින් සිසුන්ගේ වටිනා අධ්‍යාපන කාලය නාස්ති කරන බැවින්", "පෙරදිග සංගීතය හා කවි ගායනා ක්‍රමවලට විශාල ලෙස බාධා කරන බැවින්", "අධ්‍යාපනික ජන නැටුම් සිසුන්ගේ නිර්මාණශීලීත්වය හා සමාජ කුසලතා දියුණු කරයි."),
        q("සබරගමු නැටුමේදී පළඳින 'පබළු උරමාලය' සඳහා බහුලව යොදාගන්නා සාම්ප්‍රදායික වර්ණ මොනවාද?", "රතු, සුදු සහ රන්වන් පැහැය", "තද කළු සහ දුඹුරු පමණි", "අළු පැහැය පමණි", "නිල් පැහැය පමණි", "රතු හා සුදු පැහැති සබරගමු ඇඳුමට මෙම වර්ණ දීප්තිය එක් කරයි."),
        q("ජන නැටුම් අතරින් 'ලී කෙළි නැටුමේදී' ලී කෝටු සකස් කරන්නේ කෙසේද?", "වර්ණ ගැන්වූ සැහැල්ලු හා ශක්තිමත් ලී කෝටු යුගල ලෙස", "බර යකඩ පොලු ලෙස", "කටු සහිත කෝටු ලෙස", "ප්ලාස්ටික් බට ලෙස", "වැදීමේදී පැහැදිලි හඬක් නඟන සුමට ලී කෝටු භාවිත කෙරේ."),
        q("සබරගමු නැටුමේ 'ගුරු බැති පූජාව' හා 'පහන් දැල්වීම' වැඩි වශයෙන්ම සිදු කරන්නේ කුමන අවස්ථාවකදීද?", "ශාන්තිකර්ම හා පුහුණු කටයුතු ආරම්භ කිරීමට පෙර", "සියල්ල අවසන් වී නිවසට ගිය පසු", "දිවා ආහාරයෙන් පසු පමණි", "තරගය අවසානයේ පමණි", "කලා කටයුත්තකට පෙර ගෞරවය හා ආශිර්වාදය පැතීම සම්ප්‍රදායයි."),
        q("සබරගමු සම්ප්‍රදායේ 'තම්මැට්ටම' වාදනය කිරීමේදී වාදකයා එය රඳවා තබා ගන්නේ කෙසේද?", "ඉණෙහි බැඳගෙන හෝ බිම තබාගෙන කඩිප්පු දෙකෙන් වයමින්", "හිස මත තබාගෙන", "තනි අතින් ඔසවාගෙන", "උරහිසේ රඳවාගෙන", "පෙරහැරේදී ඉණේ බැඳගෙනද ශාන්තිකර්මයේදී අසුන්ගෙනද වැයිය හැකිය."),
        q("සිංහල ගැමි නැටුම් අතර 'පතල් නැටුම' නිරූපණය කරන්නේ කුමන වෘත්තීය ජීවිතයක්ද?", "මැණික් හා මිනිරන් පතල් කම්කරුවන්ගේ ශ්‍රමය හා දුක් ගැහැට", "ධීවර කාර්මිකයන්ගේ ජීවිතය", "රාජ සභා ඇමතිවරුන්ගේ ජීවිතය", "පැරණි වඩු කාර්මිකයන්ගේ ශ්‍රම ජීවිතය", "සබරගමු මැණික් පතල් ආශ්‍රිත කවි හා චලන මගින් පතල් ජීවිතය රඟ දැක්වේ."),
        q("සබරගමු නර්තන කලාවට 'පෙරහැර' මගින් ලැබී ඇති දායකත්වය කුමක්ද?", "ජනතාව අතර සම්ප්‍රදාය ජනප්‍රිය වීම හා පරම්පරාගත ශිල්පීන්ට වේදිකාව සැලසීම", "පැරණි නර්තන පද ලේඛන හා ගුරුකුල සම්ප්‍රදාය අහිමි වී යාම", "පෙරහැර ගමන් මාර්ගයේ දිගු දවුල වාදනය කිරීම සීමා වීම", "සබරගමු වන්නම් හා තේරුම් පද කවි ගායනය සම්පූර්ණයෙන් නතර වීම", "රත්නපුර මහ සමන් දේවාල පෙරහැර සබරගමු නැටුමේ ප්‍රධාන ප්‍රදර්ශන පිටියයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'සළඹ' පැළඳ හෝ අතැතිව නටන අවස්ථාව සම්බන්ධ වන්නේ කුමන දේව පූජාවටද?", "පත්තිනි දේව පූජාවට", "විෂ්ණු දේව පූජාවට පමණක්", "කතරගම පූජාවට පමණක්", "ග්‍රීක දේව පූජාවට", "සළඹ පත්තිනි මෑණියන්ගේ ප්‍රධාන ආයුධ සංකේතය ලෙස පිදුම් ලබයි."),
        q("සබරගමු නර්තන විෂය හදාරන O/L සිසුවෙකු පළමුව ප්‍රගුණ කළ යුතු මූලික ප්‍රායෝගික අංගය කුමක්ද?", "සබරගමු මට්ටි සරඹ සහ ගමන් පද", "දහඅට සන්නි මුහුණු කැපීම", "උඩරට වෙස් මංගල්‍යය", "භරත අලාරිප්පු", "මූලික සරඹ පුහුණුව සියලු සබරගමු නැටුම් අංගවලට ශක්තිමත් අත්තිවාරම දමයි."),
        q("සිංහල ජන නැටුමක් වන 'සවරම් නැටුමේදී' සවරම් කැරකවීම හා පාද චලන අතර තිබිය යුතු ගුණාංගය කුමක්ද?", "වේගවත් රිද්ම නිරවද්‍යතාව සහ අත් පා සමායෝජනය", "පාද නොසොල්වා සිටීම", "සවරම බිම දැමීම", "අනෙක් අයට බාධා කිරීම", "සමූහ නර්තනයේදී එකම රිද්මය රැකීමෙන් ඉහළ දෘශ්‍ය අලංකාරයක් ලැබේ.")
    )
}
